from decimal import Decimal,ROUND_HALF_UP
def solve(prices):
 values=[Decimal(x) for x in prices]
 if not all(x.is_finite() for x in values):raise ValueError('nonfinite')
 return str(sum((x.quantize(Decimal('.01'),rounding=ROUND_HALF_UP) for x in values),Decimal(0)).quantize(Decimal('.01'),rounding=ROUND_HALF_UP))
